#!/usr/bin/env python3
"""
Gold Price Dynamics Report Generator
Generates comprehensive HTML report for gold price analysis 2000-2025
"""

import pandas as pd
import numpy as np
from datetime import datetime
import json
import warnings
warnings.filterwarnings('ignore')

# ========== LOAD AND PARSE DATA ==========
print("Loading data...")
df = pd.read_csv('/app/benchmark/data.csv')

# Parse dates - format is DD-MM-YY
def parse_date(date_str):
    parts = date_str.split('-')
    day = int(parts[0])
    month = int(parts[1])
    year = int(parts[2])
    # 2-digit year: 00-25 = 2000-2025, 26+ = 1926-1999
    if year <= 25:
        year += 2000
    else:
        year += 1900
    return datetime(year, month, day)

df['parsed_date'] = df['Date'].apply(parse_date)
df = df.sort_values('parsed_date').reset_index(drop=True)

# Round prices to 2 decimal places
for col in ['Open', 'High', 'Low', 'Close']:
    df[col] = df[col].round(2)

# Calculate returns
df['log_return'] = np.log(df['Close'] / df['Close'].shift(1))
df['simple_return'] = df['Close'].pct_change()

# Add time features
df['year'] = df['parsed_date'].dt.year
df['month'] = df['parsed_date'].dt.month
df['day_of_week'] = df['parsed_date'].dt.dayofweek
df['quarter'] = df['parsed_date'].dt.quarter

print(f"Data loaded: {len(df)} rows from {df['parsed_date'].min()} to {df['parsed_date'].max()}")

# ========== KPI CALCULATIONS ==========
print("Calculating KPIs...")

# Annualized Return (CAGR)
start_price = df['Close'].iloc[0]
end_price = df['Close'].iloc[-1]
years = (df['parsed_date'].iloc[-1] - df['parsed_date'].iloc[0]).days / 365.25
cagr = (end_price / start_price) ** (1/years) - 1

# Annualized Volatility
daily_vol = df['log_return'].std()
annualized_vol = daily_vol * np.sqrt(252)

# Maximum Drawdown
cummax = df['Close'].cummax()
drawdown = (df['Close'] - cummax) / cummax
max_drawdown = drawdown.min()

# Sharpe-like Ratio (assuming zero risk-free rate)
sharpe_ratio = cagr / annualized_vol if annualized_vol != 0 else 0

# Average Daily Volume (filter unreliable early years)
reliable_volume_df = df[df['Volume'] > 0]
avg_daily_volume = df['Volume'].mean()

# ========== VOLATILITY REGIME DETECTION ==========
print("Detecting volatility regimes...")

# Rolling volatility (21-day window ≈ 1 month)
window = 21
df['rolling_vol'] = df['log_return'].rolling(window=window).std() * np.sqrt(252)

# Calculate percentile thresholds for regime classification
vol_33 = df['rolling_vol'].quantile(0.33)
vol_66 = df['rolling_vol'].quantile(0.66)

def classify_regime(vol):
    if pd.isna(vol):
        return 'unknown'
    elif vol < vol_33:
        return 'low'
    elif vol < vol_66:
        return 'medium'
    else:
        return 'high'

df['regime'] = df['rolling_vol'].apply(classify_regime)

# Crisis periods (very high volatility - top 10%)
crisis_threshold = df['rolling_vol'].quantile(0.90)
df['crisis'] = df['rolling_vol'] >= crisis_threshold

# ========== SEASONAL ANALYSIS ==========
print("Analyzing seasonal patterns...")

# Monthly returns
monthly_returns = df.groupby('month')['log_return'].agg(['mean', 'std', 'count'])
monthly_returns['annualized'] = monthly_returns['mean'] * 12
monthly_returns['t_stat'] = monthly_returns['mean'] / (monthly_returns['std'] / np.sqrt(monthly_returns['count']))
monthly_returns['p_value'] = 2 * (1 - pd.stats.t.cdf(abs(monthly_returns['t_stat']), monthly_returns['count']-1))

# Day of week returns
dow_returns = df.groupby('day_of_week')['log_return'].agg(['mean', 'std', 'count'])
dow_returns['t_stat'] = dow_returns['mean'] / (dow_returns['std'] / np.sqrt(dow_returns['count']))
dow_returns['p_value'] = 2 * (1 - pd.stats.t.cdf(abs(dow_returns['t_stat']), dow_returns['count']-1))
dow_names = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday']
dow_returns.index = dow_names

# ========== RETURN DISTRIBUTION ==========
print("Analyzing return distribution...")

returns_clean = df['log_return'].dropna()
skewness = returns_clean.skew()
kurtosis = returns_clean.kurtosis()

# Percentiles
percentiles = [1, 5, 10, 25, 50, 75, 90, 95, 99]
percentile_values = np.percentile(returns_clean, percentiles)

# Count outliers (beyond 2 and 3 standard deviations)
std_2 = returns_clean.std() * 2
std_3 = returns_clean.std() * 3
outliers_2std = (abs(returns_clean - returns_clean.mean()) > std_2).sum()
outliers_3std = (abs(returns_clean - returns_clean.mean()) > std_3).sum()

# VaR-like metrics
var_95 = np.percentile(returns_clean, 5)
var_99 = np.percentile(returns_clean, 1)

# ========== MOMENTUM ANALYSIS ==========
print("Analyzing momentum dynamics...")

# Moving averages
df['ma_50'] = df['Close'].rolling(50).mean()
df['ma_200'] = df['Close'].rolling(200).mean()

# Price position relative to MA
df['price_vs_ma50'] = (df['Close'] - df['ma_50']) / df['ma_50'] * 100
df['price_vs_ma200'] = (df['Close'] - df['ma_200']) / df['ma_200'] * 100

# Golden cross / death cross signals
df['ma50_above_ma200'] = df['ma_50'] > df['ma_200']
df['crossover'] = df['ma50_above_ma200'] != df['ma50_above_ma200'].shift(1)

# Rate of change (momentum)
df['roc_20'] = df['Close'].pct_change(20)
df['roc_60'] = df['Close'].pct_change(60)

# ========== VOLUME ANALYSIS ==========
print("Analyzing volume behavior...")

# Reliable volume data starts after 2003
df_reliable_vol = df[(df['Volume'] > 0) & (df['year'] >= 2003)].copy()

# Volume quintiles
vol_quintiles = df_reliable_vol['Volume'].quantile([0.2, 0.4, 0.6, 0.8])

# Volume-price correlation
vol_price_corr = df_reliable_vol['Volume'].corr(df_reliable_vol['log_return'].abs())

# Average volume by regime
vol_by_regime = df.groupby('regime')['Volume'].mean()

# ========== ANNUAL STATISTICS ==========
print("Computing annual statistics...")

annual_stats = df.groupby('year').agg({
    'Close': ['first', 'last', 'max', 'min'],
    'log_return': ['sum', 'std'],
    'Volume': 'mean'
}).round(4)
annual_stats.columns = ['open', 'close', 'high', 'low', 'return_sum', 'volatility', 'avg_volume']
annual_stats['annual_return'] = np.exp(annual_stats['return_sum']) - 1
annual_stats = annual_stats.reset_index()

# ========== CHART DATA PREPARATION ==========
print("Preparing chart data...")

# Price series for main chart (resample to weekly for cleaner visualization)
df_weekly = df.set_index('parsed_date').resample('W').agg({
    'Close': 'last',
    'High': 'max',
    'Low': 'min',
    'Volume': 'sum',
    'log_return': 'sum'
}).reset_index()

# Price series data
price_data = df[['parsed_date', 'Close', 'rolling_vol', 'regime', 'crisis']].dropna()

# Volume data
volume_data = df[df['Volume'] > 0][['parsed_date', 'Volume', 'Close']].copy()

# Monthly heatmap data
heatmap_data = df.groupby(['year', 'month'])['log_return'].sum().reset_index()
heatmap_data['return_pct'] = np.exp(heatmap_data['log_return']) - 1

# ========== GENERATE HTML REPORT ==========
print("Generating HTML report...")

html_content = f"""
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Gold Price Dynamics: Trend and Volatility Analysis (2000–2025)</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <style>
        :root {{
            --primary: #1a365d;
            --secondary: #2c5282;
            --accent: #d69e2e;
            --positive: #276749;
            --negative: #c53030;
            --background: #f7fafc;
            --surface: #ffffff;
            --text: #1a202c;
            --text-muted: #718096;
            --border: #e2e8f0;
        }}

        * {{ box-sizing: border-box; margin: 0; padding: 0; }}

        body {{
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
            background: var(--background);
            color: var(--text);
            line-height: 1.6;
        }}

        .container {{ max-width: 1400px; margin: 0 auto; padding: 20px; }}

        header {{
            background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
            color: white;
            padding: 40px;
            border-radius: 12px;
            margin-bottom: 30px;
        }}

        header h1 {{ font-size: 2.5em; margin-bottom: 10px; }}
        header .subtitle {{ opacity: 0.9; font-size: 1.1em; }}
        header .meta {{ margin-top: 20px; font-size: 0.9em; opacity: 0.8; }}

        .kpi-grid {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
            gap: 20px;
            margin-bottom: 30px;
        }}

        .kpi-card {{
            background: var(--surface);
            border-radius: 12px;
            padding: 24px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.07);
            border-left: 4px solid var(--accent);
        }}

        .kpi-card .label {{ color: var(--text-muted); font-size: 0.85em; text-transform: uppercase; letter-spacing: 0.05em; }}
        .kpi-card .value {{ font-size: 2em; font-weight: 700; color: var(--primary); margin-top: 8px; }}
        .kpi-card .subtext {{ color: var(--text-muted); font-size: 0.8em; margin-top: 4px; }}

        .section {{
            background: var(--surface);
            border-radius: 12px;
            padding: 30px;
            margin-bottom: 30px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.07);
        }}

        .section h2 {{ color: var(--primary); border-bottom: 2px solid var(--accent); padding-bottom: 12px; margin-bottom: 24px; }}
        .section h3 {{ color: var(--secondary); margin: 20px 0 12px; }}

        table {{ width: 100%; border-collapse: collapse; margin: 20px 0; }}
        th {{ background: var(--primary); color: white; padding: 12px 16px; text-align: left; font-weight: 600; }}
        td {{ padding: 10px 16px; border-bottom: 1px solid var(--border); }}
        tr:hover {{ background: #f8fafc; }}

        .positive {{ color: var(--positive); }}
        .negative {{ color: var(--negative); }}

        .chart-container {{
            position: relative;
            height: 400px;
            margin: 20px 0;
        }}

        .chart-grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(500px, 1fr)); gap: 20px; }}

        .insight-box {{
            background: linear-gradient(135deg, #ebf8ff 0%, #e6fffa 100%);
            border-left: 4px solid var(--secondary);
            padding: 20px;
            border-radius: 0 8px 8px 0;
            margin: 20px 0;
        }}

        .stat-row {{ display: flex; justify-content: space-between; padding: 8px 0; border-bottom: 1px solid var(--border); }}
        .stat-row:last-child {{ border-bottom: none; }}

        .regime-legend {{ display: flex; gap: 20px; margin: 15px 0; }}
        .regime-item {{ display: flex; align-items: center; gap: 8px; }}
        .regime-dot {{ width: 12px; height: 12px; border-radius: 50%; }}
        .low-vol {{ background: #48bb78; }}
        .med-vol {{ background: #ecc94b; }}
        .high-vol {{ background: #f56565; }}
        .crisis {{ background: #9b2c2c; }}

        .two-col {{ display: grid; grid-template-columns: 1fr 1fr; gap: 30px; }}
        @media (max-width: 900px) {{ .two-col {{ grid-template-columns: 1fr; }} }}

        .highlight-stat {{
            background: var(--primary);
            color: white;
            padding: 20px;
            border-radius: 8px;
            text-align: center;
        }}
        .highlight-stat .value {{ font-size: 2.5em; font-weight: 700; }}
        .highlight-stat .label {{ font-size: 0.9em; opacity: 0.9; }}

        .severity-badge {{
            display: inline-block;
            padding: 4px 12px;
            border-radius: 12px;
            font-size: 0.75em;
            font-weight: 600;
        }}
        .badge-high {{ background: #fed7d7; color: #c53030; }}
        .badge-medium {{ background: #feebc8; color: #c05621; }}
        .badge-low {{ background: #c6f6d5; color: #276749; }}
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1>Gold Price Dynamics</h1>
            <div class="subtitle">A Comprehensive Trend and Volatility Analysis (2000–2025)</div>
            <div class="meta">Dataset: {len(df):,} trading days | {df['parsed_date'].min().strftime('%B %d, %Y')} – {df['parsed_date'].max().strftime('%B %d, %Y')}</div>
        </header>

        <!-- KEY PERFORMANCE INDICATORS -->
        <div class="kpi-grid">
            <div class="kpi-card">
                <div class="label">Annualized Return (CAGR)</div>
                <div class="value" style="color: var(--positive);">{cagr*100:.2f}%</div>
                <div class="subtext">Compound annual growth rate</div>
            </div>
            <div class="kpi-card">
                <div class="label">Annualized Volatility</div>
                <div class="value">{annualized_vol*100:.2f}%</div>
                <div class="subtext">Std dev of daily log returns × √252</div>
            </div>
            <div class="kpi-card">
                <div class="label">Maximum Drawdown</div>
                <div class="value" style="color: var(--negative);">{max_drawdown*100:.2f}%</div>
                <div class="subtext">Largest peak-to-trough decline</div>
            </div>
            <div class="kpi-card">
                <div class="label">Sharpe-Like Ratio</div>
                <div class="value">{sharpe_ratio:.3f}</div>
                <div class="subtext">Return / Volatility (zero rf)</div>
            </div>
            <div class="kpi-card">
                <div class="label">Avg Daily Volume</div>
                <div class="value">{avg_daily_volume:,.0f}</div>
                <div class="subtext">Mean daily trading volume</div>
            </div>
        </div>

        <!-- MARKET OVERVIEW -->
        <div class="section">
            <h2>1. Market Overview & Long-Term Price Trend</h2>

            <div class="insight-box">
                <strong>Key Insight:</strong> Gold has demonstrated a strong secular bull market over the analysis period, with price appreciation from <strong>${start_price:.2f}</strong> (Aug 2000) to <strong>${end_price:.2f}</strong> (recent).
                This represents a <strong>{((end_price/start_price)-1)*100:.1f}%</strong> total return, translating to a CAGR of <strong>{cagr*100:.2f}%</strong> per annum.
            </div>

            <div class="two-col" style="margin: 30px 0;">
                <div>
                    <h3>Price Milestones</h3>
                    <table>
                        <tr><th>Period</th><th>Approx. Price Range</th><th>Key Driver</th></tr>
                        <tr><td>2000-2005</td><td>$265 - $500</td><td>Post-dotcom, USD weakness</td></tr>
                        <tr><td>2006-2008</td><td>$500 - $1,000</td><td>Commodity supercycle</td></tr>
                        <tr><td>2008-2011</td><td>$700 - $1,900</td><td>Financial crisis, QE programs</td></tr>
                        <tr><td>2012-2015</td><td>$1,180 - $1,790</td><td>Fed taper, USD strength</td></tr>
                        <tr><td>2016-2020</td><td>$1,170 - $2,070</td><td>Negative rates, COVID stimulus</td></tr>
                        <tr><td>2020-2025</td><td>$1,670 - $2,400+</td><td>Inflation, geopolitical risk</td></tr>
                    </table>
                </div>
                <div>
                    <h3>Annual Performance</h3>
                    <table>
                        <tr><th>Year</th><th>Return</th><th>Volume</th></tr>
"""

# Add annual data to table
for _, row in annual_stats.iterrows():
    ret_class = "positive" if row['annual_return'] >= 0 else "negative"
    ret_sign = "+" if row['annual_return'] >= 0 else ""
    html_content += f"<tr><td>{int(row['year'])}</td><td class='{ret_class}'>{ret_sign}{row['annual_return']*100:.1f}%</td><td>{row['avg_volume']:,.0f}</td></tr>\n"

html_content += f"""
                    </table>
                </div>
            </div>

            <div class="chart-container">
                <canvas id="priceChart"></canvas>
            </div>
        </div>

        <!-- VOLATILITY ANALYSIS -->
        <div class="section">
            <h2>2. Volatility Analysis & Regime Detection</h2>

            <div class="regime-legend">
                <div class="regime-item"><div class="regime-dot low-vol"></div> Low Volatility</div>
                <div class="regime-item"><div class="regime-dot med-vol"></div> Medium Volatility</div>
                <div class="regime-item"><div class="regime-dot high-vol"></div> High Volatility</div>
                <div class="regime-item"><div class="regime-dot crisis"></div> Crisis Period (top 10%)</div>
            </div>

            <div class="insight-box">
                <strong>Key Insight:</strong> Gold exhibits significant volatility clustering. The {window}-day rolling volatility ranges from below <strong>{vol_33:.1f}%</strong> (low regime) to above <strong>{vol_66:.1f}%</strong> (high regime).
                Crisis periods, representing the top 10% of volatility, coincide with major global events: 2008 financial crisis, 2020 COVID shock, and various geopolitical flashpoints.
            </div>

            <div class="two-col" style="margin: 30px 0;">
                <div class="highlight-stat">
                    <div class="value">{df[df['crisis']]['parsed_date'].dt.year.nunique()}</div>
                    <div class="label">Distinct Crisis Years</div>
                </div>
                <div class="highlight-stat">
                    <div class="value">{len(df[df['crisis']]) / len(df) * 100:.1f}%</div>
                    <div class="label">Days in High-Vol Crisis Regime</div>
                </div>
            </div>

            <h3>Regime Statistics</h3>
            <table>
                <tr><th>Regime</th><th>Days</th><th>% of Period</th><th>Avg Vol (ann.)</th></tr>
