#!/usr/bin/env python3
"""
Gold Price Dynamics Report Generator
Generates comprehensive HTML report for gold price analysis 2000-2025
"""

import pandas as pd
import numpy as np
from datetime import datetime
import json
import warnings
warnings.filterwarnings('ignore')

# ========== LOAD AND PARSE DATA ==========
print("Loading data...")
df = pd.read_csv('/app/benchmark/data.csv')

# Parse dates - format is DD-MM-YY
def parse_date(date_str):
    parts = date_str.split('-')
    day = int(parts[0])
    month = int(parts[1])
    year = int(parts[2])
    # 2-digit year: 00-25 = 2000-2025, 26+ = 1926-1999
    if year <= 25:
        year += 2000
    else:
        year += 1900
    return datetime(year, month, day)

df['parsed_date'] = df['Date'].apply(parse_date)
df = df.sort_values('parsed_date').reset_index(drop=True)

# Round prices to 2 decimal places
for col in ['Open', 'High', 'Low', 'Close']:
    df[col] = df[col].round(2)

# Calculate returns
df['log_return'] = np.log(df['Close'] / df['Close'].shift(1))
df['simple_return'] = df['Close'].pct_change()

# Add time features
df['year'] = df['parsed_date'].dt.year
df['month'] = df['parsed_date'].dt.month
df['day_of_week'] = df['parsed_date'].dt.dayofweek
df['quarter'] = df['parsed_date'].dt.quarter

print(f"Data loaded: {len(df)} rows from {df['parsed_date'].min()} to {df['parsed_date'].max()}")

# ========== KPI CALCULATIONS ==========
print("Calculating KPIs...")

# Annualized Return (CAGR)
start_price = df['Close'].iloc[0]
end_price = df['Close'].iloc[-1]
years = (df['parsed_date'].iloc[-1] - df['parsed_date'].iloc[0]).days / 365.25
cagr = (end_price / start_price) ** (1/years) - 1

# Annualized Volatility
daily_vol = df['log_return'].std()
annualized_vol = daily_vol * np.sqrt(252)

# Maximum Drawdown
cummax = df['Close'].cummax()
drawdown = (df['Close'] - cummax) / cummax
max_drawdown = drawdown.min()

# Sharpe-like Ratio (assuming zero risk-free rate)
sharpe_ratio = cagr / annualized_vol if annualized_vol != 0 else 0

# Average Daily Volume (filter unreliable early years)
reliable_volume_df = df[df['Volume'] > 0]
avg_daily_volume = df['Volume'].mean()

# ========== VOLATILITY REGIME DETECTION ==========
print("Detecting volatility regimes...")

# Rolling volatility (21-day window ≈ 1 month)
window = 21
df['rolling_vol'] = df['log_return'].rolling(window=window).std() * np.sqrt(252)

# Calculate percentile thresholds for regime classification
vol_33 = df['rolling_vol'].quantile(0.33)
vol_66 = df['rolling_vol'].quantile(0.66)

def classify_regime(vol):
    if pd.isna(vol):
        return 'unknown'
    elif vol < vol_33:
        return 'low'
    elif vol < vol_66:
        return 'medium'
    else:
        return 'high'

df['regime'] = df['rolling_vol'].apply(classify_regime)

# Crisis periods (very high volatility - top 10%)
crisis_threshold = df['rolling_vol'].quantile(0.90)
df['crisis'] = df['rolling_vol'] >= crisis_threshold

# ========== SEASONAL ANALYSIS ==========
print("Analyzing seasonal patterns...")

# Monthly returns
monthly_returns = df.groupby('month')['log_return'].agg(['mean', 'std', 'count'])
monthly_returns['annualized'] = monthly_returns['mean'] * 12
monthly_returns['t_stat'] = monthly_returns['mean'] / (monthly_returns['std'] / np.sqrt(monthly_returns['count']))
monthly_returns['p_value'] = 2 * (1 - pd.stats.t.cdf(abs(monthly_returns['t_stat']), monthly_returns['count']-1))

# Day of week returns
dow_returns = df.groupby('day_of_week')['log_return'].agg(['mean', 'std', 'count'])
dow_returns['t_stat'] = dow_returns['mean'] / (dow_returns['std'] / np.sqrt(dow_returns['count']))
dow_returns['p_value'] = 2 * (1 - pd.stats.t.cdf(abs(dow_returns['t_stat']), dow_returns['count']-1))
dow_names = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday']
dow_returns.index = dow_names

# ========== RETURN DISTRIBUTION ==========
print("Analyzing return distribution...")

returns_clean = df['log_return'].dropna()
skewness = returns_clean.skew()
kurtosis = returns_clean.kurtosis()

# Percentiles
percentiles = [1, 5, 10, 25, 50, 75, 90, 95, 99]
percentile_values = np.percentile(returns_clean, percentiles)

# Count outliers (beyond 2 and 3 standard deviations)
std_2 = returns_clean.std() * 2
std_3 = returns_clean.std() * 3
outliers_2std = (abs(returns_clean - returns_clean.mean()) > std_2).sum()
outliers_3std = (abs(returns_clean - returns_clean.mean()) > std_3).sum()

# VaR-like metrics
var_95 = np.percentile(returns_clean, 5)
var_99 = np.percentile(returns_clean, 1)

# ========== MOMENTUM ANALYSIS ==========
print("Analyzing momentum dynamics...")

# Moving averages
df['ma_50'] = df['Close'].rolling(50).mean()
df['ma_200'] = df['Close'].rolling(200).mean()

# Price position relative to MA
df['price_vs_ma50'] = (df['Close'] - df['ma_50']) / df['ma_50'] * 100
df['price_vs_ma200'] = (df['Close'] - df['ma_200']) / df['ma_200'] * 100

# Golden cross / death cross signals
df['ma50_above_ma200'] = df['ma_50'] > df['ma_200']
df['crossover'] = df['ma50_above_ma200'] != df['ma50_above_ma200'].shift(1)

# Rate of change (momentum)
df['roc_20'] = df['Close'].pct_change(20)
df['roc_60'] = df['Close'].pct_change(60)

# ========== VOLUME ANALYSIS ==========
print("Analyzing volume behavior...")

# Reliable volume data starts after 2003
df_reliable_vol = df[(df['Volume'] > 0) & (df['year'] >= 2003)].copy()

# Volume quintiles
vol_quintiles = df_reliable_vol['Volume'].quantile([0.2, 0.4, 0.6, 0.8])

# Volume-price correlation
vol_price_corr = df_reliable_vol['Volume'].corr(df_reliable_vol['log_return'].abs())

# Average volume by regime
vol_by_regime = df.groupby('regime')['Volume'].mean()

# ========== ANNUAL STATISTICS ==========
print("Computing annual statistics...")

annual_stats = df.groupby('year').agg({
    'Close': ['first', 'last', 'max', 'min'],
    'log_return': ['sum', 'std'],
    'Volume': 'mean'
}).round(4)
annual_stats.columns = ['open', 'close', 'high', 'low', 'return_sum', 'volatility', 'avg_volume']
annual_stats['annual_return'] = np.exp(annual_stats['return_sum']) - 1
annual_stats = annual_stats.reset_index()

# ========== CHART DATA PREPARATION ==========
print("Preparing chart data...")

# Price series for main chart (resample to weekly for cleaner visualization)
df_weekly = df.set_index('parsed_date').resample('W').agg({
